import SwiftUI
import SwiftData
import OSLog

/// Real Demo Data toggle (replaces the former NotYetAvailableView placeholder).
/// State is derived from actual persisted `Deck.isDemo` rows, never a separate
/// flag that could drift from reality — toggling reflects what is truly on disk.
struct DemoDataSettingsView: View {
    private enum LoadState: Equatable {
        case loading
        case ready(isSeeded: Bool)
        case error(String)
    }

    @Environment(\.modelContext) private var modelContext
    @State private var loadState: LoadState = .loading
    @State private var isBusy = false

    private static let logger = Logger(subsystem: "com.recallapp.ios", category: "DemoData")

    var body: some View {
        VStack(alignment: .leading, spacing: DS.Space.m) {
            switch loadState {
            case .loading:
                LoadingStateView(message: "Checking demo data…", testId: "demoData.loading")

            case .error(let message):
                ErrorStateView(
                    message: message,
                    retry: { Task { await refresh() } },
                    testId: "demoData.error"
                )

            case .ready(let isSeeded):
                content(isSeeded: isSeeded)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .background(DS.Palette.background)
        .navigationTitle("Demo Data")
        .task {
            await refresh()
        }
    }

    @ViewBuilder
    private func content(isSeeded: Bool) -> some View {
        VStack(alignment: .leading, spacing: DS.Space.m) {
            VStack(alignment: .leading, spacing: DS.Space.s) {
                Text("Seed example data")
                    .font(DS.Font.headline)
                    .foregroundStyle(DS.Palette.textPrimary)

                Text("Adds two example decks — Spanish Basics and World Capitals — with a realistic review history, so Study and Stats aren't empty on first look. Turn off to remove them completely; nothing else is affected.")
                    .font(DS.Font.body)
                    .foregroundStyle(DS.Palette.textSecondary)

                Toggle(
                    "Enable demo data",
                    isOn: Binding(
                        get: { isSeeded },
                        set: { newValue in
                            Task { await setEnabled(newValue) }
                        }
                    )
                )
                .toggleStyle(.switch)
                .disabled(isBusy)
                .accessibilityIdentifier("demoData.enableToggle")
                .accessibilityLabel("Enable demo data")

                if isBusy {
                    HStack(spacing: DS.Space.xs) {
                        ProgressView()
                        Text(isSeeded ? "Removing…" : "Seeding…")
                            .font(DS.Font.caption)
                            .foregroundStyle(DS.Palette.textSecondary)
                    }
                    .accessibilityIdentifier("demoData.busy")
                }

                if isSeeded {
                    DemoDataTag()
                        .accessibilityIdentifier("demoData.activeTag")
                }
            }
            .padding(DS.Space.m)
            .background(DS.Palette.surface)
            .clipShape(RoundedRectangle(cornerRadius: DS.Radius.card))
        }
        .padding(DS.Space.m)
    }

    private func refresh() async {
        do {
            let seeder = DemoDataSeeder(context: modelContext)
            let seeded = try seeder.isSeeded()
            loadState = .ready(isSeeded: seeded)
        } catch {
            Self.logger.error("Failed to read demo data state: \(error.localizedDescription, privacy: .public)")
            loadState = .error("Couldn't check demo data status. Try again.")
        }
    }

    private func setEnabled(_ enabled: Bool) async {
        guard !isBusy else { return }
        isBusy = true
        defer { isBusy = false }

        let seeder = DemoDataSeeder(context: modelContext)
        do {
            if enabled {
                try seeder.seed()
            } else {
                try seeder.removeAll()
            }
            loadState = .ready(isSeeded: enabled)
        } catch {
            Self.logger.error("Demo data toggle failed: \(error.localizedDescription, privacy: .public)")
            // Never claim a state that didn't happen — surface the failure honestly
            // rather than silently leaving the toggle in a state that doesn't match disk.
            loadState = .error(enabled ? "Couldn't add demo data. Try again." : "Couldn't remove demo data. Try again.")
        }
    }
}

