import SwiftUI
import SwiftData
import OSLog
import RecallCSV

/// Real CSV export (replaces the former NotYetAvailableView placeholder).
/// Lets the user pick one deck, builds the CSV with the shared, pure
/// CSVParser.exportCSV (RecallCSV package — no re-implementation here), writes
/// it to a temp file, and hands off to the system share sheet so the user can
/// save it to Files, AirDrop it, etc.
struct CSVExportView: View {
    private enum LoadState: Equatable {
        case loading
        case empty
        case loaded([DeckSummary])
        case error(String)
    }

    private struct DeckSummary: Identifiable, Equatable {
        let id: UUID
        let name: String
        let cardCount: Int
    }

    @Environment(\.modelContext) private var modelContext
    let onClose: () -> Void

    @State private var loadState: LoadState = .loading
    @State private var selectedDeckID: UUID?
    @State private var exportFileURL: URL?
    @State private var exportError: String?
    @State private var isPreparingExport = false

    private static let logger = Logger(subsystem: "com.recallapp.ios", category: "CSVExport")

    var body: some View {
        NavigationStack {
            content
                .navigationTitle("Export to CSV")
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button("Close", action: onClose)
                            .accessibilityIdentifier("csvExport.closeButton")
                    }
                }
                .task {
                    await refresh()
                }
        }
    }

    @ViewBuilder
    private var content: some View {
        switch loadState {
        case .loading:
            LoadingStateView(message: "Loading decks…", testId: "csvExport.loading")

        case .error(let message):
            ErrorStateView(
                message: message,
                retry: { Task { await refresh() } },
                testId: "csvExport.error"
            )

        case .empty:
            EmptyStateView(
                iconName: "square.and.arrow.up",
                title: "No decks to export",
                subtitle: "Create a deck with some cards first, then come back here to export it to CSV.",
                testId: "csvExport.empty"
            )

        case .loaded(let decks):
            deckPickerContent(decks: decks)
        }
    }

    @ViewBuilder
    private func deckPickerContent(decks: [DeckSummary]) -> some View {
        VStack(spacing: 0) {
            List {
                Section {
                    ForEach(Array(decks.enumerated()), id: \.element.id) { index, deck in
                        HStack {
                            VStack(alignment: .leading, spacing: 2) {
                                Text(deck.name)
                                    .font(DS.Font.body)
                                    .foregroundStyle(DS.Palette.textPrimary)
                                Text("\(deck.cardCount) card\(deck.cardCount == 1 ? "" : "s")")
                                    .font(DS.Font.caption)
                                    .foregroundStyle(DS.Palette.textSecondary)
                            }
                            Spacer()
                            if selectedDeckID == deck.id {
                                Image(systemName: "checkmark.circle.fill")
                                    .foregroundStyle(DS.Palette.accentAmber)
                            }
                        }
                        .contentShape(Rectangle())
                        .onTapGesture {
                            selectedDeckID = deck.id
                            exportFileURL = nil
                            exportError = nil
                        }
                        .accessibilityIdentifier("csvExport.deckPicker_\(index)")
                        .accessibilityLabel(Text("\(deck.name), \(deck.cardCount) cards"))
                        .accessibilityAddTraits(selectedDeckID == deck.id ? [.isSelected] : [])
                    }
                } header: {
                    Text("Choose a deck")
                }
            }
            .listStyle(.insetGrouped)
            .scrollContentBackground(.hidden)
            .background(DS.Palette.background)

            if let exportError {
                Text(exportError)
                    .font(DS.Font.caption)
                    .foregroundStyle(DS.Palette.danger)
                    .padding(.horizontal, DS.Space.m)
                    .accessibilityIdentifier("csvExport.exportError")
            }

            exportControl
                .padding(DS.Space.m)
        }
    }

    @ViewBuilder
    private var exportControl: some View {
        if let exportFileURL {
            ShareLink(item: exportFileURL) {
                HStack {
                    Spacer()
                    if isPreparingExport {
                        ProgressView()
                    } else {
                        Text("Export \"\(selectedDeckName ?? "deck")\"")
                            .font(DS.Font.bodyEmphasized)
                    }
                    Spacer()
                }
                .frame(height: 44)
            }
            .buttonStyle(.borderedProminent)
            .disabled(isPreparingExport)
            .accessibilityIdentifier("csvExport.exportButton")
            .accessibilityLabel("Export \(selectedDeckName ?? "deck") to CSV")
        } else {
            Button {
                Task { await prepareExport() }
            } label: {
                HStack {
                    Spacer()
                    if isPreparingExport {
                        ProgressView()
                    } else {
                        Text("Export")
                            .font(DS.Font.bodyEmphasized)
                    }
                    Spacer()
                }
                .frame(height: 44)
            }
            .buttonStyle(.borderedProminent)
            .disabled(selectedDeckID == nil || isPreparingExport)
            .accessibilityIdentifier("csvExport.exportButton")
            .accessibilityLabel("Export selected deck to CSV")
        }
    }

    private var selectedDeckName: String? {
        guard case .loaded(let decks) = loadState else { return nil }
        return decks.first(where: { $0.id == selectedDeckID })?.name
    }

    private func refresh() async {
        do {
            let repository = SwiftDataDeckRepository(context: modelContext)
            let decks = try repository.fetchAllDecks(includeArchived: true)
            let summaries = decks.map { DeckSummary(id: $0.id, name: $0.name, cardCount: $0.cards.count) }

            if summaries.isEmpty {
                loadState = .empty
            } else {
                loadState = .loaded(summaries)
                if selectedDeckID == nil {
                    selectedDeckID = summaries.first?.id
                }
            }
        } catch {
            Self.logger.error("Failed to load decks for export: \(error.localizedDescription, privacy: .public)")
            loadState = .error("Couldn't load your decks. Try again.")
        }
    }

    private func prepareExport() async {
        guard let selectedDeckID, !isPreparingExport else { return }
        isPreparingExport = true
        defer { isPreparingExport = false }
        exportError = nil

        do {
            let repository = SwiftDataDeckRepository(context: modelContext)
            guard let deck = try repository.fetchAllDecks(includeArchived: true).first(where: { $0.id == selectedDeckID }) else {
                exportError = "That deck couldn't be found. It may have been deleted."
                return
            }

            let rows = deck.cards.map { (front: $0.front, back: $0.back, note: $0.note) }
            let csvData = CSVParser.exportCSV(cards: rows)

            let fileName = sanitizedFileName(for: deck.name)
            let url = FileManager.default.temporaryDirectory.appendingPathComponent(fileName)
            try csvData.write(to: url, options: .atomic)
            exportFileURL = url
        } catch {
            Self.logger.error("CSV export failed: \(error.localizedDescription, privacy: .public)")
            exportError = "Couldn't prepare the export file. Try again."
        }
    }

    private func sanitizedFileName(for deckName: String) -> String {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_ "))
        let cleaned = deckName.unicodeScalars.filter { allowed.contains($0) }
        let base = String(String.UnicodeScalarView(cleaned)).trimmingCharacters(in: .whitespaces)
        return "\(base.isEmpty ? "deck" : base).csv"
    }
}

