/// Frozen shape per interfaces.json (owning_lane polish_resilience). Seeds/removes
/// two demo decks with a realistic review history, computed via the real
/// SM2Engine (not fabricated numbers) so Study/Stats screens are never empty on
/// first look, per the original prompt's "demo data" toggle requirement.
/// `removeAll` relies on Deck -> Card -> ReviewLog cascade delete rules already
/// on the schema, so it leaves zero residue in counts (DEC-initial_discussion-005).
public struct DemoDataSeeder {
    private let context: ModelContext

    public init(context: ModelContext) {
        self.context = context
    }

    public func isSeeded() throws -> Bool {
        var descriptor = FetchDescriptor<Deck>(predicate: #Predicate { $0.isDemo == true })
        descriptor.fetchLimit = 1
        return try !context.fetch(descriptor).isEmpty
    }

    public func seed() throws {
        guard try !isSeeded() else { return }

        let calendar = Calendar.current
        let now = Date()

        for spec in Self.deckSpecs {
            let deckCreatedAt = calendar.date(byAdding: .day, value: -30, to: now) ?? now
            let deck = Deck(name: spec.name, createdAt: deckCreatedAt, isDemo: true)
            context.insert(deck)

            for (cardIndex, cardSpec) in spec.cards.enumerated() {
                try seedCard(cardSpec, index: cardIndex, deck: deck, now: now, calendar: calendar)
            }
        }

        try context.save()
    }

    public func removeAll() throws {
        let descriptor = FetchDescriptor<Deck>(predicate: #Predicate { $0.isDemo == true })
        let demoDecks = try context.fetch(descriptor)
        guard !demoDecks.isEmpty else { return }

        for deck in demoDecks {
            context.delete(deck)
        }
        try context.save()
    }

    // MARK: - Simulation

    private func seedCard(
        _ spec: CardSpec,
        index: Int,
        deck: Deck,
        now: Date,
        calendar: Calendar
    ) throws {
        let reviewCount = spec.gradeSequence.count
        let startDaysAgo = 7 * reviewCount + (index % 3)
        var reviewDate = calendar.date(byAdding: .day, value: -startDaysAgo, to: now) ?? now

        let card = Card(
            front: spec.front,
            back: spec.back,
            note: spec.note,
            dueDate: now,
            isDemo: true,
            createdAt: reviewDate,
            deck: deck
        )
        context.insert(card)

        var state = SchedulingState(easeFactor: 2.5, intervalDays: 0, repetitionCount: 0)
        var lastReviewDate = reviewDate

        for grade in spec.gradeSequence {
            let nextState = SM2Engine.schedule(current: state, grade: grade)

            let log = ReviewLog(
                timestamp: reviewDate,
                grade: grade.rawValue,
                easeFactorBefore: state.easeFactor,
                easeFactorAfter: nextState.easeFactor,
                intervalBefore: state.intervalDays,
                intervalAfter: nextState.intervalDays,
                repetitionBefore: state.repetitionCount,
                repetitionAfter: nextState.repetitionCount,
                card: card
            )
            context.insert(log)

            state = nextState
            lastReviewDate = reviewDate
            let nextInterval = max(nextState.intervalDays, 1)
            let candidate = calendar.date(byAdding: .day, value: nextInterval, to: reviewDate) ?? reviewDate
            reviewDate = min(candidate, now)
        }

        card.easeFactor = state.easeFactor
        card.intervalDays = state.intervalDays
        card.repetitionCount = state.repetitionCount
        card.lastReviewedAt = lastReviewDate
        card.dueDate = SM2Engine.calculateNextDueDate(
            from: lastReviewDate,
            intervalDays: max(state.intervalDays, 1),
            calendar: calendar
        )
    }

